<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model { protected $fillable=['name','sku','category_id','brand_id','unit_id','cost_price','selling_price','reorder_level','is_active','description']; protected $casts=['cost_price'=>'decimal:2','selling_price'=>'decimal:2','reorder_level'=>'decimal:3','is_active'=>'boolean']; public function category(){return $this->belongsTo(Category::class);} public function brand(){return $this->belongsTo(Brand::class);} public function unit(){return $this->belongsTo(Unit::class);} public function stocks(){return $this->hasMany(WarehouseStock::class);} public function getTotalStockAttribute(){return (float)$this->stocks->sum('quantity');} public function getStockStatusAttribute(){return $this->total_stock <= (float)$this->reorder_level ? 'Low stock' : 'In stock';} }
